1	const priceList: Record<string, number> = {
2	  sword: 100,
3	  amulet: 60,
4	  staff: 80,
5	  potion: 40,
6	  rune: 25,
7	  moonstone: 25,
8	};
9	
10	type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };
11	
12	const COMPONENT_BLOCK_SIZE = 3;
13	const COMPONENT_BLOCK_PRICE = 60;
14	
15	const COMPONENT_TYPES = ["rune", "moonstone"];
16	
17	const sumOfItemPrices = (items: Item[]): number =>
18	  items.reduce((sum, item) => sum + priceList[item.type], 0);
19	
20	const countOf = (type: string, items: Item[]): number =>
21	  items.filter((item) => item.type === type).length;
22	
23	const componentPremium = (type: string, items: Item[]): number => {
24	  const count = countOf(type, items);
25	  return count === COMPONENT_BLOCK_SIZE
26	    ? COMPONENT_BLOCK_PRICE
27	    : count * priceList[type];
28	};
29	
30	export const basePremium = (items: Item[]): number => {
31	  const nonComponents = items.filter(
32	    (item) => !COMPONENT_TYPES.includes(item.type),
33	  );
34	  const componentsTotal = COMPONENT_TYPES.reduce(
35	    (total, type) => total + componentPremium(type, items),
36	    0,
37	  );
38	  return sumOfItemPrices(nonComponents) + componentsTotal;
39	};
40	
41	const PROCESSING_FEE = 5;
42	const CURSE_SURCHARGE_RATE = 0.5;
43	const HIGH_ENCHANTMENT_RATE = 0.3;
44	const HIGH_ENCHANTMENT_THRESHOLD = 5;
45	const FIRST_INSURANCE_RATE = 0.1;
46	
47	const curseSurchargeFor = (item: Item): number =>
48	  item.cursed ? basePremium([item]) * CURSE_SURCHARGE_RATE : 0;
49	
50	const enchantSurchargeFor = (item: Item): number =>
51	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
52	    ? basePremium([item]) * HIGH_ENCHANTMENT_RATE
53	    : 0;
54	
55	const surchargesFor = (item: Item): number =>
56	  curseSurchargeFor(item) + enchantSurchargeFor(item);
57	
58	const quotePremium = (items: Item[]): number => {
59	  const policyBase = basePremium(items);
60	  const itemSurcharges = items.reduce(
61	    (sum, item) => sum + surchargesFor(item),
62	    0,
63	  );
64	  const firstInsurance = policyBase * FIRST_INSURANCE_RATE;
65	  return policyBase + itemSurcharges + firstInsurance + PROCESSING_FEE;
66	};
67	
68	type QuoteStep = { op: "quote"; items: Item[] };
69	type Scenario = { customer: { yearsWithMHPCO: number }; steps: QuoteStep[] };
70	
71	export const runScenario = (scenario: Scenario): { results: { premium: number }[] } => {
72	  const results = scenario.steps.map((step) => ({
73	    premium: quotePremium(step.items),
74	  }));
75	  return { results };
76	};
